tree.polydeukes.config.yaml:
sessionDisciplines:
  - id: fe
    declare:
      mechanism: precedent
      sources:
        sc: {sidecar: true}
      extract:
        hit:
          - {op: source, of: sc}
          - {op: json}
          - {op: items}
          - {op: filter, when: [{field: n, eq: 1.0}]}
      relate:
        - id: r
          relation: {op: nonEmpty, of: hit}
          message: "none {key}"
